'use strict';
const HERO_ITEMS={sword:{name:'Miecz wędrowca',slot:'weapon',description:'+1 do obrażeń bohatera',price:80},shield:{name:'Tarcza dębowa',slot:'shield',description:'25% mniej obrażeń bohatera',price:70},amulet:{name:'Amulet odnowy',slot:'amulet',description:'50% szybsze leczenie po walce',price:90}};
function roamingState(){state.roaming??={inventory:{sword:0,shield:0,amulet:0},loot:[],merchantClock:30,visit:0,quests:{}};return state.roaming}
function giveHeroItem(kind,key){const s=roamingState();if(!HERO_ITEMS[kind]||s.loot.includes(key))return false;s.inventory[kind]++;s.loot.push(key);save();return true}
function equipHeroItem(uid,kind){const s=roamingState(),u=state.war.guards.find(u=>u.uid===uid&&u.hero),d=HERO_ITEMS[kind];if(!u||!d||s.inventory[kind]<1)return false;u.gear??={};if(u.gear[d.slot]===kind)return false;if(u.gear[d.slot])s.inventory[u.gear[d.slot]]++;s.inventory[kind]--;u.gear[d.slot]=kind;save();renderRoaming(true);return true}
function unequipHeroItem(uid,slot){const s=roamingState(),u=state.war.guards.find(u=>u.uid===uid&&u.hero);if(!u?.gear?.[slot])return false;s.inventory[u.gear[slot]]++;delete u.gear[slot];save();renderRoaming(true);return true}
const roamingDamage=soldierDamage;soldierDamage=function(u){return roamingDamage(u)+(u.hero&&u.gear?.weapon==='sword'?1:0)};
const roamingArmor=armorDamage;armorDamage=function(amount,u){return roamingArmor(amount)*(u?.hero&&u.gear?.shield==='shield'?.75:1)};
const roamingHealing=healDefender;healDefender=function(u,dt){const before=u.restTime||0;roamingHealing(u,dt);if(u.hero&&u.gear?.amulet==='amulet'&&u.hp>0&&u.hp<8&&!u.fighting){const extra=Math.max(0,(u.restTime||0)-6)-Math.max(0,before-6);u.hp=Math.min(8,u.hp+extra*.25)}};
const roamingLoot=adventureLoot;adventureLoot=function(id){const result=roamingLoot(id);if(result){const kind={cart:'sword',shrine:'amulet',ruins:'shield'}[id];if(kind&&giveHeroItem(kind,'place:'+id))say('Znaleziono: '+HERO_ITEMS[kind].name+'. Otwórz Bohaterowie i kupcy.')}return result};
const roamingCamp=attackAdventureCamp;attackAdventureCamp=function(id){const result=roamingCamp(id);if(result){const r=state.war.raids.find(r=>r.camp===id);r.archers=Math.min(3,Math.ceil(r.power/6));r.bowCooldown=1;save()}return result};
function drawBanditArcher(u){drawArcherUnit(u);ctx.fillStyle='#a65549';ctx.fillRect(u.x-7,u.y-18,14,16);polygon([[u.x-9,u.y-25],[u.x,u.y-35],[u.x+8,u.y-25]],'#854334')}
function updateBanditBows(dt){const troops=[...state.war.guards,...state.war.patrols.flatMap(p=>p.units)];for(const r of state.war.raids){if(!r.camp||r.power<=0)continue;r.archers??=Math.min(3,Math.ceil(r.power/6));r.bowCooldown=Math.max(0,(r.bowCooldown??1)-dt);if(r.bowCooldown>0)continue;const p=routePosition(r),targets=troops.filter(u=>u.hp>0&&Math.hypot(u.x-p.x,u.y-p.y)<=5*T&&arrowClearLine(p,u)).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y));if(!targets.length)continue;const u=targets[0];r.bowCooldown=1.8;r.banditShot={x:p.x,y:p.y-20,tx:u.x,ty:u.y-20,time:state.time};u.hp=Math.max(0,u.hp-armorDamage(.45*Math.min(r.archers,Math.ceil(r.power/6)),u));u.restTime=0;u.healing=false;u.lastBanditHit=state.time}for(let i=state.war.guards.length-1;i>=0;i--)if(state.war.guards[i].hp<=0){state.war.guards.splice(i,1);state.war.soldiers--;save()}for(const p of state.war.patrols)p.units=p.units.filter(u=>u.hp>0)}
function nearbyTravelPoint(radius=10){const o=villageOrigin();for(let r=radius;r>=4;r--)for(const [dx,dy] of [[-r,0],[0,r],[0,-r],[r,0]]){const x=o.x+dx,y=o.y+dy;if(npcWalkable(x,y)&&!foreignBuilding(x,y)){const route=campaignRoute({x,y},o,false);if(route)return {x,y,route}}}return null}
function spawnWanderingMerchant(){const s=roamingState();if(s.merchant||!state.settled)return false;const p=nearbyTravelPoint();if(!p){s.merchantClock=20;return false}s.visit++;s.merchant={route:p.route,progress:0,phase:'travel',remaining:90,age:0,stock:{food:40,stone:40,sword:1,shield:1,amulet:1}};save();say('Wędrowny kupiec jedzie do osady.');return true}
function tradeWanderingMerchant(kind){const s=roamingState(),m=s.merchant;if(!m||m.phase!=='visit'){say('Kupiec jeszcze nie dotarł do osady.');return false}const p=routePosition(m);if(Math.hypot(state.p.x-p.x,state.p.y-p.y)>3*T){say('Podejdź do kupca na 3 pola.');return false}if(HERO_ITEMS[kind]){const d=HERO_ITEMS[kind];if(!m.stock[kind]||state.gold<d.price)return false;state.gold-=d.price;m.stock[kind]--;s.inventory[kind]++}else if(['food','stone'].includes(kind)){if(m.stock[kind]<10||state.gold<12||state[kind]+10>capacity())return false;state.gold-=12;state[kind]+=10;m.stock[kind]-=10}else if(kind==='sellWood'){if(state.wood<10||m.boughtWood>=40)return false;state.wood-=10;state.gold+=8;m.boughtWood=(m.boughtWood||0)+10}else return false;save();ui();renderRoaming(true);return true}
function locateWanderingMerchant(){const m=roamingState().merchant;if(!m)return false;const p=routePosition(m);state.clock.mapTarget={x:p.x/T,y:p.y/T};save();return true}
function storySidequestsAllowed(){return !!state.story?.active||!!adventureState()?.started&&!adventureState()?.completed}
function startScoutQuest(){if(!storySidequestsAllowed())return false;const s=roamingState();if(s.quests.scout)return false;const point=nearbyTravelPoint(16);if(!point)return false;s.quests.scout={x:point.x,y:point.y,done:false};save();renderRoaming(true);return true}
function rescueScout(){const s=roamingState(),q=s.quests.scout;if(!storySidequestsAllowed()||!q||q.done||Math.hypot(state.p.x/T-q.x-.5,state.p.y/T-q.y-.5)>2.5)return false;q.done=true;state.gold+=60;s.inventory.amulet++;save();ui();renderRoaming(true);say('Zwiadowca uratowany! Przekazał Ci amulet i 60 monet.');return true}
function startEscortQuest(){if(!storySidequestsAllowed())return false;const s=roamingState();if(s.quests.escort&&!s.quests.escort.failed)return false;const p=nearbyTravelPoint(12);if(!p)return false;state.war.raids=state.war.raids.filter(r=>r.camp!=='escort-ambush');s.quests.escort={route:p.route,progress:0,hp:40,done:false,failed:false,ambush:false};save();renderRoaming(true);return true}
function updateRoaming(dt){const s=state.roaming;if(!s)return;if(state.settled){if(!s.merchant){s.merchantClock-=dt;if(s.merchantClock<=0)spawnWanderingMerchant()}else{const m=s.merchant;m.age+=dt;if(m.phase==='travel'){advanceCampaign(m,dt,1.3);if(m.progress>=m.route.length-1){m.phase='visit';say('Kupiec dotarł! Przez 90 sekund czeka przy osadzie.')}}else m.remaining-=dt;if(m.remaining<=0||m.age>240){delete s.merchant;s.merchantClock=120;save()}}}const q=s.quests.escort;if(storySidequestsAllowed()&&q&&!q.done&&!q.failed){const p=routePosition(q),near=state.war.guards.some(u=>u.hp>0&&Math.hypot(u.x-p.x,u.y-p.y)<4*T);q.waiting=!near;const r=state.war.raids.find(r=>r.camp==='escort-ambush');if(r){q.hp=Math.max(0,q.hp-dt*.5);if(q.hp<=0){q.failed=true;state.war.raids=state.war.raids.filter(r=>r.camp!=='escort-ambush');save();say('Wóz stracony. Możesz spróbować ponownie.')}}else if(near){advanceCampaign(q,dt,1);if(!q.ambush&&q.progress>=Math.min(3,q.route.length-1)){q.ambush=true;const at=routePosition(q);state.war.raids.push({townId:'escort-ambush',camp:'escort-ambush',power:10,archers:1,progress:0,route:[{x:at.x/T,y:at.y/T},{x:at.x/T,y:at.y/T}],hostile:true});say('Zasadzka na wóz! Pokonaj bandytów.');save()}else if(q.progress>=q.route.length-1){q.done=true;state.gold+=80;s.inventory.sword++;save();say('Wóz bezpieczny! +80 monet i miecz dla bohatera.')}}}}
const roamingWar=updateWar;updateWar=function(dt){updateBanditBows(dt);const defeated=state.war.raids.filter(r=>r.camp);roamingWar(dt);for(const r of defeated)if(r.power<=0&&!state.war.raids.includes(r))giveHeroItem('shield','camp:'+r.camp);updateRoaming(dt)};
let roamingSignature='';
function renderRoaming(force=false){if($('roamingPanel').classList.contains('hidden'))return;const s=roamingState(),heroes=state.war.guards.filter(u=>u.hero),m=s.merchant,q=s.quests,signature=JSON.stringify([s.inventory,heroes.map(u=>[u.uid,u.hero,u.gear]),m&&[m.phase,m.stock,m.boughtWood],q,storySidequestsAllowed(),Math.floor(state.gold)]);const timer=$('merchantTime'),next=$('merchantNext');if(timer)timer.textContent=Math.ceil(m?.remaining||0);if(next)next.textContent=Math.ceil(Math.max(0,s.merchantClock));if(!force&&signature===roamingSignature)return;roamingSignature=signature;const button=(action,label,id='',disabled=false)=>`<button data-roaming="${action}" data-id="${id}" ${disabled?'disabled':''}>${label}</button>`;let html='<p>Łucznicy bandytów, przedmioty i kupcy działają w grze swobodnej. Fabularne zadania wymagają aktywnej opowieści.</p><h3>Ekwipunek bohaterów</h3><p>Przedmioty znajdziesz przy skarbach, w obozach albo kupisz u wędrowca. Bohatera awansujesz w panelu Rozwój i pory roku.</p>';for(const [kind,d] of Object.entries(HERO_ITEMS))html+='<p>'+d.name+' · '+d.description+' · w plecaku: '+s.inventory[kind]+'</p>';for(const u of heroes){html+='<section class="adventure-card"><b>Bohater · poziom '+u.hero.level+'</b>';for(const [kind,d] of Object.entries(HERO_ITEMS))html+=button(u.gear?.[d.slot]===kind?'unequip':'equip',u.gear?.[d.slot]===kind?'Zdejmij: '+d.name:'Załóż: '+d.name,u.uid+':'+(u.gear?.[d.slot]===kind?d.slot:kind),u.gear?.[d.slot]!==kind&&!s.inventory[kind]);html+='</section>'}if(!heroes.length)html+='<p>Nie masz bohatera w garnizonie. Awansuj żołnierza lub odwołaj swojego bohatera do osady.</p>';html+='<h3>Wędrowny kupiec</h3>';if(!m)html+='<p>Następna wizyta za około <span id="merchantNext">'+Math.ceil(Math.max(0,s.merchantClock))+'</span> sekund aktywnej gry. Wymaga założonej osady.</p>';else{html+='<p>'+(m.phase==='visit'?'Kupiec czeka: <span id="merchantTime">'+Math.ceil(m.remaining)+'</span> s':'Kupiec jedzie do osady.')+'</p>'+button('merchantLocate','Wskaż kupca');for(const [kind,d] of Object.entries(HERO_ITEMS))html+=button('buy',d.name+' · '+d.price+' monet',kind,m.phase!=='visit'||!m.stock[kind]||state.gold<d.price);html+=button('buy','10 żywności · 12 monet','food',m.phase!=='visit'||m.stock.food<10)+button('buy','10 kamienia · 12 monet','stone',m.phase!=='visit'||m.stock.stone<10)+button('buy','Sprzedaj 10 drewna · +8 monet','sellWood',m.phase!=='visit'||m.boughtWood>=40)}html+='<h3>Zadania fabularne</h3>';if(!storySidequestsAllowed())html+='<p>Zadania eskorty i zwiadowcy są dostępne tylko podczas aktywnej fabuły. Otwórz Tryb fabularny lub rozpocznij kampanię II.</p>';else{html+='<p>Zaginiony zwiadowca: '+(q.scout?.done?'uratowany':q.scout?'czeka na pomoc':'Mira prosi o pomoc')+'</p>'+button('scoutStart','Przyjmij poszukiwania','',!!q.scout);if(q.scout&&!q.scout.done)html+=button('scoutLocate','Wskaż zwiadowcę')+button('scoutRescue','Udziel pomocy · podejdź na 2 pola');html+='<p>Eskorta wozu: '+(q.escort?.done?'wóz dostarczony':q.escort?.failed?'porażka — spróbuj ponownie':q.escort?q.escort.waiting?'czeka na żołnierza w promieniu 4 pól':'w drodze · '+Math.ceil(q.escort.hp)+'/40 PŻ':'przyprowadź żołnierzy do wozu. Nagroda: 80 monet i miecz.')+'</p>'+button('escortStart','Przyjmij eskortę','',!!q.escort&&!q.escort.failed);if(q.escort&&!q.escort.done&&!q.escort.failed)html+=button('escortLocate','Wskaż wóz')}html+='<h3>Obozy w grze swobodnej</h3><p>Otwórz Przygody i kampania II → Rozpocznij przygody. Nie musisz uruchamiać fabuły. W obozach czekają także łucznicy strzelający na 5 pól.</p>';$('roamingContent').innerHTML=html}
$('roamingOpen').onclick=()=>{roamingState();$('roamingPanel').classList.remove('hidden');renderRoaming(true)};$('roamingClose').onclick=()=>$('roamingPanel').classList.add('hidden');$('roamingContent').onclick=e=>{const b=e.target.closest('[data-roaming]');if(!b)return;const id=b.dataset.id;switch(b.dataset.roaming){case 'equip':equipHeroItem(...id.split(':'));break;case 'unequip':unequipHeroItem(...id.split(':'));break;case 'buy':tradeWanderingMerchant(id);break;case 'merchantLocate':locateWanderingMerchant();break;case 'scoutStart':startScoutQuest();break;case 'scoutRescue':rescueScout();break;case 'escortStart':startEscortQuest();break;case 'scoutLocate':case 'escortLocate':{const q=roamingState().quests[b.dataset.roaming==='scoutLocate'?'scout':'escort'];if(q){const p=q.route?routePosition(q):{x:(q.x+.5)*T,y:(q.y+.5)*T};state.clock.mapTarget={x:p.x/T,y:p.y/T};save()}break}}};
const roamingUI=ui;ui=function(){roamingUI();renderRoaming()};
const roamingWorld=drawWarWorld;drawWarWorld=function(){roamingWorld();for(const r of state.war.raids){const s=r.banditShot;if(!s||state.time-s.time>.4)continue;const f=(state.time-s.time)/.4;ctx.strokeStyle='#ffb69b';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(s.x+(s.tx-s.x)*f,s.y+(s.ty-s.y)*f);ctx.lineTo(s.x+(s.tx-s.x)*f-8,s.y+(s.ty-s.y)*f-3);ctx.stroke();ctx.lineWidth=1}const s=state.roaming;if(!s)return;const drawWagon=(e,label,color)=>{const p=routePosition(e);if(!seen.has(tileKey(Math.floor(p.x/T),Math.floor(p.y/T))))return;ctx.fillStyle=color;ctx.fillRect(p.x-17,p.y-23,34,22);ctx.fillStyle='#413b2b';ctx.beginPath();ctx.arc(p.x-11,p.y,6,0,7);ctx.arc(p.x+11,p.y,6,0,7);ctx.fill();ctx.fillStyle='#f1deb0';ctx.font='10px system-ui';ctx.fillText(label,p.x-20,p.y-32)};if(s.merchant)drawWagon(s.merchant,'KUPIEC','#c4a56a');if(s.quests.escort&&!s.quests.escort.done&&!s.quests.escort.failed)drawWagon(s.quests.escort,'ESKORTA','#a9bb80');const q=s.quests.scout;if(q&&!q.done&&seen.has(tileKey(q.x,q.y))){drawTrooper((q.x+.5)*T,(q.y+.5)*T,'#889e77',q);ctx.fillStyle='#f4df9a';ctx.fillText('ZWIADOWCA',(q.x+.5)*T-28,(q.y+.5)*T-40)}};
const roamingStructure=structure;structure=function(b,x,y){if(!['mlyn','stajnia','drwal'].includes(b.type)){roamingStructure(b,x,y);return}ctx.fillStyle='#24392b55';ctx.beginPath();ctx.ellipse(x,y+12,27,10,0,0,7);ctx.fill();if(b.type==='mlyn'){ctx.fillStyle='#cbc5a0';polygon([[x-18,y+12],[x-13,y-36],[x+13,y-36],[x+18,y+12]],'#cbc5a0');polygon([[x-19,y-36],[x,y-55],[x+19,y-36]],'#855c45');ctx.fillStyle='#534333';ctx.fillRect(x-5,y-3,10,15);ctx.strokeStyle='#e9dab3';ctx.lineWidth=5;const a=state.time*1.5;for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(x,y-24);ctx.lineTo(x+Math.cos(a+i*Math.PI/2)*30,y-24+Math.sin(a+i*Math.PI/2)*30);ctx.stroke()}ctx.lineWidth=1}else if(b.type==='stajnia'){ctx.fillStyle='#bda471';ctx.fillRect(x-25,y-20,50,32);polygon([[x-30,y-20],[x-17,y-37],[x+18,y-37],[x+30,y-20]],'#725240');ctx.fillStyle='#4a4030';for(const dx of [-19,3])ctx.fillRect(x+dx,y-12,16,24);ctx.fillStyle='#c8ad77';ctx.fillRect(x-7,y-8,14,7);ctx.fillRect(x+3,y-17,7,14);ctx.fillRect(x-6,y-1,3,9);ctx.fillRect(x+3,y-1,3,9)}else{ctx.fillStyle='#95714a';ctx.fillRect(x-19,y-18,38,30);ctx.strokeStyle='#614c36';for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(x-19,y-14+i*7);ctx.lineTo(x+19,y-14+i*7);ctx.stroke()}polygon([[x-25,y-18],[x,y-40],[x+25,y-18]],'#516b4a');ctx.fillStyle='#493e2f';ctx.fillRect(x-4,y-5,10,17);for(let i=0;i<3;i++){ctx.fillStyle='#785a38';ctx.fillRect(x-27,y+4+i*5,17,4);ctx.fillStyle='#d4b278';ctx.beginPath();ctx.arc(x-10,y+6+i*5,3,0,7);ctx.fill()}ctx.strokeStyle='#b0ada1';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x+16,y-7);ctx.lineTo(x+24,y-25);ctx.stroke();ctx.lineWidth=1}};
window.addEventListener('keydown',e=>{if(e.key==='Escape')$('roamingPanel').classList.add('hidden')});

roamingState();
